using Microsoft.EntityFrameworkCore;
public interface IMessageBus
{
    Task PublishAsync<T>(T message, CancellationToken ct);
    Task PublishAsync(string type, string payload, CancellationToken ct);
}
public sealed record OrderPlaced(Guid OrderId, Guid CustomerId, decimal Total)
    : Mediator.INotification;
public sealed class OutboxMessage
{
    public long Id { get; set; }
    public string Type { get; set; } = "";
    public string Payload { get; set; } = "";
    public DateTime? PublishedAt { get; set; }
    public static OutboxMessage From<T>(T message) where T : notnull => new()
    {
        Type = typeof(T).Name,
        Payload = System.Text.Json.JsonSerializer.Serialize(message),
    };
}
public sealed class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<OutboxMessage> Outbox => Set<OutboxMessage>();
}
